<?php
namespace App\Jobs;
use App\Contracts\SmsProvider; use App\Models\Booking; use Illuminate\Bus\Queueable; use Illuminate\Contracts\Queue\ShouldQueue; use Illuminate\Foundation\Bus\Dispatchable; use Illuminate\Queue\InteractsWithQueue; use Illuminate\Queue\SerializesModels; use Illuminate\Support\Facades\Mail; use Throwable;
class EventCancellationNoticeJob implements ShouldQueue {use Dispatchable,InteractsWithQueue,Queueable,SerializesModels;public int $tries=5;public array $backoff=[10,30,90,300,600];public function __construct(public int $bookingId){}public function handle(SmsProvider $sms):void{$b=Booking::with(['user','event'])->findOrFail($this->bookingId);$text='تم إلغاء فعالية '.$b->event->title.'، وتم تسجيل استرداد قيمة الحجز رقم '.$b->id.'.';$key='event-cancel-'.$b->id;if($b->user->email)cache()->lock('lock:'.$key.':email',120)->block(10,function()use($b,$key,$text){if(cache()->has('sent:'.$key.':email'))return;Mail::raw($text,fn($m)=>$m->to($b->user->email)->subject('تحديث بخصوص فعاليتك'));cache()->put('sent:'.$key.':email',true,2592000);});if($b->user->phone)cache()->lock('lock:'.$key.':sms',120)->block(10,function()use($b,$sms,$key,$text){if(cache()->has('sent:'.$key.':sms'))return;$sms->send($b->user->phone,$text,$key.':sms');cache()->put('sent:'.$key.':sms',true,2592000);});}public function failed(?Throwable $e):void{logger()->critical('Event cancellation notice failed',['booking_id'=>$this->bookingId,'error'=>$e?->getMessage()]);}}
